166	/// Card types.
167	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
168	pub enum CardType {
169	    Land,
170	    Creature,
171	    Instant,
172	    Sorcery,
173	    Enchantment,
174	    Artifact,
175	    Planeswalker,
176	}
177	
178	impl CardType {
179	    pub fn is_permanent(&self) -> bool {
180	        matches!(self, CardType::Land | CardType::Creature | CardType::Enchantment
181	            | CardType::Artifact | CardType::Planeswalker)
182	    }
183	}
184	
185	/// Supertypes.
186	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
187	pub enum Supertype {
188	    Basic,
189	    Legendary,
190	    Snow,
191	}
192	
193	/// Zones where objects can exist.
194	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
195	pub enum Zone {
196	    Library,
197	    Hand,
198	    Battlefield,
199	    Graveyard,
200	    Stack,
201	    Exile,
202	    Command,
203	}
204	
205	/// Turn phases.
206	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
207	pub enum Phase {
208	    Beginning,
209	    PrecombatMain,
210	    Combat,
211	    PostcombatMain,
212	    Ending,
213	}
214	
215	/// Steps within phases.
216	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
217	pub enum Step {
218	    Untap,
219	    Upkeep,
220	    Draw,
221	    PrecombatMain,
222	    BeginCombat,
223	    DeclareAttackers,
224	    DeclareBlockers,
225	    CombatDamage,
226	    EndCombat,
227	    PostcombatMain,
228	    EndStep,
229	    Cleanup,
230	}
231	
232	impl Step {
233	    pub fn phase(&self) -> Phase {
234	        match self {
235	            Step::Untap | Step::Upkeep | Step::Draw => Phase::Beginning,
236	            Step::PrecombatMain => Phase::PrecombatMain,
237	            Step::BeginCombat | Step::DeclareAttackers | Step::DeclareBlockers
238	                | Step::CombatDamage | Step::EndCombat => Phase::Combat,
239	            Step::PostcombatMain => Phase::PostcombatMain,
240	            Step::EndStep | Step::Cleanup => Phase::Ending,
241	        }
242	    }
243	
244	    pub fn next(&self) -> Option<Step> {
245	        match self {
246	            Step::Untap => Some(Step::Upkeep),
247	            Step::Upkeep => Some(Step::Draw),
248	            Step::Draw => Some(Step::PrecombatMain),
249	            Step::PrecombatMain => Some(Step::BeginCombat),
250	            Step::BeginCombat => Some(Step::DeclareAttackers),
251	            Step::DeclareAttackers => Some(Step::DeclareBlockers),
252	            Step::DeclareBlockers => Some(Step::CombatDamage),
253	            Step::CombatDamage => Some(Step::EndCombat),
254	            Step::EndCombat => Some(Step::PostcombatMain),
255	            Step::PostcombatMain => Some(Step::EndStep),
256	            Step::EndStep => Some(Step::Cleanup),
257	            Step::Cleanup => None, // end of turn
258	        }
259	    }
260	
261	    /// Does this step normally grant priority to players?
262	    pub fn has_priority(&self) -> bool {
263	        match self {
264	            Step::Untap => false,
265	            Step::Cleanup => false, // normally no priority unless triggered abilities fire
266	            _ => true,
267	        }
268	    }
269	
270	    /// Is this a main phase step where sorcery-speed actions are allowed?
271	    pub fn is_main_phase(&self) -> bool {
272	        matches!(self, Step::PrecombatMain | Step::PostcombatMain)
273	    }
274	}
