276	/// Counter types that can exist on permanents.
277	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
278	pub enum CounterType {
279	    PlusOnePlusOne,
280	    MinusOneMinusOne,
281	    Loyalty,
282	    Slime,
283	    Study,
284	    // extend as needed
285	}
286	
287	/// Keyword abilities.
288	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
289	pub enum Keyword {
290	    Flying,
291	    FirstStrike,
292	    DoubleStrike,
293	    Trample,
294	    Deathtouch,
295	    Lifelink,
296	    Vigilance,
297	    Flash,
298	    Reach,
299	    Haste,
300	    Defender,
301	    Hexproof,
302	    Intimidate,
303	    Menace,
304	    Indestructible,
305	}
