387	/// Condition for conditional effects.
388	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
389	pub enum EffectCondition {
390	    /// You control a permanent with this subtype.
391	    YouControlSubtype(String),
392	    /// An opponent controls a permanent with this subtype.
393	    OpponentControlsSubtype(String),
394	    /// This permanent has the specified keyword (for conditional abilities like
395	    /// "has indestructible as long as it has defender").
396	    SelfHasKeyword(Keyword),
397	}
