408	#[cfg(test)]
409	mod tests {
410	    use super::*;
411	
412	    #[test]
413	    fn mana_cost_value() {
414	        // {2}{R}{R} = 4
415	        let cost = ManaCost::new(vec![
416	            ManaSymbol::Generic(2),
417	            ManaSymbol::Colored(Color::Red),
418	            ManaSymbol::Colored(Color::Red),
419	        ]);
420	        assert_eq!(cost.mana_value(), 4);
421	    }
422	
423	    #[test]
424	    fn mana_cost_colored_requirements() {
425	        let cost = ManaCost::new(vec![
426	            ManaSymbol::Generic(1),
427	            ManaSymbol::Colored(Color::Green),
428	            ManaSymbol::Colored(Color::Green),
429	        ]);
430	        let reqs = cost.colored_requirements();
431	        assert_eq!(reqs.get(&Color::Green), Some(&2));
432	        assert_eq!(cost.generic_amount(), 1);
433	    }
434	
435	    #[test]
436	    fn mana_cost_display() {
437	        let cost = ManaCost::new(vec![
438	            ManaSymbol::Generic(2),
439	            ManaSymbol::Colored(Color::Red),
440	        ]);
441	        assert_eq!(format!("{}", cost), "{2}{R}");
442	    }
443	
444	    #[test]
445	    fn mana_pool_operations() {
446	        let mut pool = ManaPool::new();
447	        assert!(pool.is_empty());
448	
449	        pool.add(ManaType::Green, 2);
